import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a hexagonal tiling of the plane by unit regular hexagons (side length 1), consider the convex hexagonal cluster whose six side lengths, in clockwise order and aligned with the tiling directions, are {a}, {b}, {c}, {a}, {b}, {c}. A walkway is built as a single contiguous ring of unit hexagons surrounding this cluster by occupying precisely those hexagons that lie within [t_a] layers of the two sides of length {a}, within [t_b] layers of the two sides of length {b}, and within [t_c] layers of the two sides of length {c}. The garden is the region enclosed by the walkway, not including the walkway itself. Its area can be written as m·(√3/2) square units for some positive integer m. Compute the remainder when m is divided by {modulus}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate a,b,c as pairwise distinct side lengths
# Ensure t_a, t_b, t_c are positive and less than their corresponding side lengths
# Ensure interior lengths u=a-t_a, v=b-t_b, w=c-t_c are >=1
# Avoid symmetric/easy cases and trivial moduli
def gen_once():
    a = rng.randint(40, 400)
    b = rng.randint(40, 400)
    c = rng.randint(40, 400)
    # enforce pairwise distinct for harder geometry
    if len({a, b, c}) < 3:
        return None
    # thicknesses
    t_a = rng.randint(1, max(1, a - 1))
    t_b = rng.randint(1, max(1, b - 1))
    t_c = rng.randint(1, max(1, c - 1))
    # interior lengths
    u = a - t_a
    v = b - t_b
    w = c - t_c
    if min(u, v, w) < 1:
        return None
    # avoid degenerate or overly symmetric instances
    if len({t_a, t_b, t_c}) < 2:
        return None
    if len({u, v, w}) < 2:
        return None
    # modulus selection
    mod_choices = [997, 999, 1000, 1009, 1021, 1231, 2047]
    modulus = rng.choice(mod_choices)
    # compute m to avoid answer=0 mod modulus too often
    H = u*v + v*w + w*u - (u + v + w) + 1
    m = 3 * H
    if m <= 0:
        return None
    # avoid trivial zero remainder
    if m % modulus == 0:
        return None
    # also avoid tiny m
    if m < 10**5:
        return None
    return {
        'a': a,
        'b': b,
        'c': c,
        't_a': t_a,
        't_b': t_b,
        't_c': t_c,
        'modulus': modulus
    }
# retry loop
for _ in range(1000):
    res = gen_once()
    if res is not None:
        return res
# fallback deterministic hard case
a, b, c = 301, 257, 349
t_a, t_b, t_c = 73, 41, 86
modulus = 1009
return {
    'a': a, 'b': b, 'c': c,
    't_a': t_a, 't_b': t_b, 't_c': t_c,
    'modulus': modulus
}

    def verifier(assign):
# Validate inputs and compute the remainder answer
# Returns (True, answer) on success; (False, None) on invalid instance
try:
    a = int(assign['a'])
    b = int(assign['b'])
    c = int(assign['c'])
    t_a = int(assign['t_a'])
    t_b = int(assign['t_b'])
    t_c = int(assign['t_c'])
    modulus = int(assign['modulus'])
except Exception:
    # Missing or bad types
    return (False, None)
# Basic domain checks
if min(a, b, c) < 1 or min(t_a, t_b, t_c) < 1:
    # Side lengths and thicknesses must be positive
    return (False, None)
# Interior side lengths
u = a - t_a
v = b - t_b
w = c - t_c
if min(u, v, w) < 1:
    # The garden (interior) must be nonempty
    return (False, None)
# Avoid symmetric/easy instances (enforce difficulty)
if len({a, b, c}) < 3:
    return (False, None)  # all equal or two equal sides is too easy
if len({t_a, t_b, t_c}) < 2:
    return (False, None)  # uniform thickness too easy
if len({u, v, w}) < 2:
    return (False, None)
if modulus <= 1:
    return (False, None)
# Compute m via the discrete hex-cluster formula
# Number of unit hexagons in cluster with alternating side-lengths (u, v, w, u, v, w):
# H = uv + vw + wu - (u + v + w) + 1
H = u*v + v*w + w*u - (u + v + w) + 1
m = 3 * H  # since each unit hex has area 3*(sqrt(3)/2);
if m <= 0:
    return (False, None)
# Additional difficulty guard: avoid trivial zero remainder
if m % modulus == 0:
    return (False, None)
answer = m % modulus
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

